final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >
  IoT Core device onboarding policy created through a Lambda-backed custom resource
  (Node.js 24.x). Devices may connect, publish, receive, and subscribe only on topics
  scoped to their own thing name.

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DeviceOnboarding
    AllowedPattern: '^[A-Za-z0-9_+=,.@-]{1,64}$'
    ConstraintDescription: 1-64 characters from [A-Za-z0-9_+=,.@-].
    Description: Prefix for the generated IoT policy name.
  TopicPrefix:
    Type: String
    Default: devices
    AllowedPattern: '^[A-Za-z0-9_/-]{1,64}$'
    ConstraintDescription: 1-64 characters from [A-Za-z0-9_/-].
    Description: Root topic namespace. Devices are limited to <TopicPrefix>/<thingName>/*.

Resources:
  IotPolicyFunctionLogGroup:
    Type: AWS::Logs::LogGroup
    DeletionPolicy: Delete
    UpdateReplacePolicy: Delete
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-iot-policy-provider'
      RetentionInDays: 14

  IotPolicyFunctionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: IotPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: WriteLogs
                Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !Sub '${IotPolicyFunctionLogGroup.Arn}:*'
              - Sid: ManageScopedIotPolicies
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicy
                  - iot:DeletePolicyVersion
                  - iot:GetPolicy
                  - iot:ListPolicyVersions
                Resource: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${PolicyNamePrefix}-*'
              - Sid: DetachOnDelete
                Effect: Allow
                Action:
                  - iot:ListTargetsForPolicy
                  - iot:DetachPolicy
                Resource: '*'

  IotPolicyFunction:
    Type: AWS::Lambda::Function
    DependsOn: IotPolicyFunctionLogGroup
    Properties:
      FunctionName: !Sub '${AWS::StackName}-iot-policy-provider'
      Description: Custom resource provider that manages an IoT Core device onboarding policy.
      Runtime: nodejs24.x
      Handler: index.handler
      Timeout: 120
      MemorySize: 256
      Role: !GetAtt IotPolicyFunctionRole.Arn
      LoggingConfig:
        LogGroup: !Ref IotPolicyFunctionLogGroup
      Code:
        ZipFile: |
          const https = require('https');
          const crypto = require('crypto');
          const {
            IoTClient,
            CreatePolicyCommand,
            CreatePolicyVersionCommand,
            DeletePolicyCommand,
            DeletePolicyVersionCommand,
            DetachPolicyCommand,
            GetPolicyCommand,
            ListPolicyVersionsCommand,
            ListTargetsForPolicyCommand
          } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});
          const VALID_NAME = /^[\w+=,.@-]{1,128}$/;
          const MAX_POLICY_VERSIONS = 5;

          function sanitize(value) {
            return String(value || '').replace(/[^\w+=,.@-]/g, '-');
          }

          function generatePolicyName(prefix, stackName) {
            const suffix = crypto.randomBytes(4).toString('hex');
            const base = (sanitize(prefix) + '-' + sanitize(stackName)).slice(0, 128 - suffix.length - 1);
            return base + '-' + suffix;
          }

          function isNotFound(err) {
            return err && err.name === 'ResourceNotFoundException';
          }

          function sendResponse(event, context, status, data, physicalId, reason) {
            const body = JSON.stringify({
              Status: status,
              Reason: reason || ('See CloudWatch Logs: ' + context.logStreamName),
              PhysicalResourceId: physicalId || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              NoEcho: false,
              Data: data || {}
            });
            const url = new URL(event.ResponseURL);
            return new Promise((resolve, reject) => {
              const req = https.request({
                hostname: url.hostname,
                port: 443,
                path: url.pathname + url.search,
                method: 'PUT',
                headers: { 'Content-Type': '', 'Content-Length': Buffer.byteLength(body) }
              }, (res) => {
                res.on('data', () => {});
                res.on('end', resolve);
              });
              req.on('error', reject);
              req.write(body);
              req.end();
            });
          }

          async function createPolicy(name, document) {
            await iot.send(new CreatePolicyCommand({ policyName: name, policyDocument: document }));
          }

          async function updatePolicyDocument(name, document) {
            const { policyVersions = [] } = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
            if (policyVersions.length >= MAX_POLICY_VERSIONS) {
              const oldest = policyVersions
                .filter((v) => !v.isDefaultVersion)
                .sort((a, b) => new Date(a.createDate) - new Date(b.createDate))[0];
              if (oldest) {
                await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: oldest.versionId }));
              }
            }
            await iot.send(new CreatePolicyVersionCommand({
              policyName: name,
              policyDocument: document,
              setAsDefault: true
            }));
          }

          async function deletePolicy(name) {
            try {
              let marker;
              do {
                const res = await iot.send(new ListTargetsForPolicyCommand({ policyName: name, marker, pageSize: 250 }));
                for (const target of res.targets || []) {
                  await iot.send(new DetachPolicyCommand({ policyName: name, target }));
                }
                marker = res.nextMarker;
              } while (marker);

              const { policyVersions = [] } = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
              for (const v of policyVersions) {
                if (!v.isDefaultVersion) {
                  await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: v.versionId }));
                }
              }
              await iot.send(new DeletePolicyCommand({ policyName: name }));
            } catch (err) {
              if (!isNotFound(err)) throw err;
              console.log('Policy ' + name + ' not found; nothing to delete.');
            }
          }

          exports.handler = async (event, context) => {
            console.log(JSON.stringify(Object.assign({}, event, { ResponseURL: '<redacted>' })));

            const props = event.ResourceProperties || {};
            let physicalId = event.PhysicalResourceId;
            let responded = false;

            const respond = async (status, data, reason) => {
              if (responded) return;
              responded = true;
              await sendResponse(event, context, status, data, physicalId, reason);
            };

            const timer = setTimeout(() => {
              respond('FAILED', {}, 'Custom resource handler timed out').catch((e) => console.error(e));
            }, Math.max(context.getRemainingTimeInMillis() - 5000, 1000));

            try {
              let data = {};

              if (event.RequestType === 'Create') {
                physicalId = generatePolicyName(props.PolicyNamePrefix, props.StackName);
                await createPolicy(physicalId, props.PolicyDocument);
              } else if (event.RequestType === 'Update') {
                const old = event.OldResourceProperties || {};
                if (old.PolicyNamePrefix !== props.PolicyNamePrefix || !VALID_NAME.test(physicalId || '')) {
                  // New physical ID; CloudFormation will issue a Delete for the old policy.
                  physicalId = generatePolicyName(props.PolicyNamePrefix, props.StackName);
                  await createPolicy(physicalId, props.PolicyDocument);
                } else if (old.PolicyDocument !== props.PolicyDocument) {
                  await updatePolicyDocument(physicalId, props.PolicyDocument);
                }
              } else if (event.RequestType === 'Delete') {
                if (physicalId && VALID_NAME.test(physicalId)) {
                  await deletePolicy(physicalId);
                } else {
                  console.log('Physical ID is not a policy name; skipping delete.');
                }
              }

              if (event.RequestType !== 'Delete') {
                const policy = await iot.send(new GetPolicyCommand({ policyName: physicalId }));
                data = { PolicyName: policy.policyName, PolicyArn: policy.policyArn };
              }

              clearTimeout(timer);
              await respond('SUCCESS', data);
            } catch (err) {
              console.error(err);
              clearTimeout(timer);
              await respond('FAILED', {}, (err && err.message ? err.message : String(err)).slice(0, 1000));
            }
          };

  DeviceOnboardingPolicy:
    Type: Custom::IotPolicy
    Properties:
      ServiceToken: !GetAtt IotPolicyFunction.Arn
      ServiceTimeout: 300
      PolicyNamePrefix: !Ref PolicyNamePrefix
      StackName: !Ref AWS::StackName
      PolicyDocument: !Sub |
        {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Sid": "ConnectAsOwnThing",
              "Effect": "Allow",
              "Action": "iot:Connect",
              "Resource": "arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:client/${!iot:Connection.Thing.ThingName}",
              "Condition": {
                "Bool": {
                  "iot:Connection.Thing.IsAttached": "true"
                }
              }
            },
            {
              "Sid": "PublishAndReceiveOwnTopics",
              "Effect": "Allow",
              "Action": [
                "iot:Publish",
                "iot:Receive"
              ],
              "Resource": "arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topic/${TopicPrefix}/${!iot:Connection.Thing.ThingName}/*"
            },
            {
              "Sid": "SubscribeOwnTopics",
              "Effect": "Allow",
              "Action": "iot:Subscribe",
              "Resource": "arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:topicfilter/${TopicPrefix}/${!iot:Connection.Thing.ThingName}/*"
            }
          ]
        }

Outputs:
  PolicyName:
    Description: Name of the generated IoT Core device onboarding policy.
    Value: !GetAtt DeviceOnboardingPolicy.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IotPolicyName'
  PolicyArn:
    Description: ARN of the generated IoT Core device onboarding policy.
    Value: !GetAtt DeviceOnboardingPolicy.PolicyArn

AWSTemplateFormatVersion: "2010-09-09"
Description: >
  Self-contained AppSync GraphQL API (CryptoTickerAPI) that fetches current cryptocurrency
  prices from CoinGecko via an HTTP data source, stores historical price records in DynamoDB
  through a pipeline resolver, and exposes paginated price history.

Resources:
  APIDataTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: APIDataTable
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: hk
          AttributeType: S
        - AttributeName: sk
          AttributeType: S
      KeySchema:
        - AttributeName: hk
          KeyType: HASH
        - AttributeName: sk
          KeyType: RANGE
      SSESpecification:
        SSEEnabled: false

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                  - dynamodb:BatchGetItem
                  - dynamodb:BatchWriteItem
                Resource:
                  - !GetAtt APIDataTable.Arn
                  - !Sub "${APIDataTable.Arn}/index/*"
        - PolicyName: AppSyncLogging
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "*"

  CryptoTickerAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: CryptoTickerAPI
      AuthenticationType: API_KEY

  CryptoTickerSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Definition: |
        schema {
          query: Query
        }

        type Query {
          ticker(symbol: String!): TickerInfo
        }

        type TickerInfo {
          ticker: String!
          priceUsd: Float
          timestamp: AWSDateTime
          priceHistory(limit: Int, nextToken: String): PriceHistoryConnection
        }

        type PriceRecord {
          ticker: String!
          priceUsd: Float
          timestamp: AWSDateTime
        }

        type PriceHistoryConnection {
          items: [PriceRecord]
          nextToken: String
        }

  CryptoTickerApiKey:
    Type: AWS::AppSync::ApiKey
    DependsOn: CryptoTickerSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Description: Default API key for CryptoTickerAPI

  CoinGeckoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Name: CoinGeckoHttpDataSource
      Description: HTTP data source for the CoinGecko public API
      Type: HTTP
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      HttpConfig:
        Endpoint: https://api.coingecko.com

  APIDataTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Name: APIDataTableDataSource
      Description: DynamoDB data source for historical ticker prices
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref APIDataTable
        AwsRegion: !Ref AWS::Region

  FetchPriceFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: CryptoTickerSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Name: FetchPriceFromCoinGecko
      Description: Fetches the current USD price for a ticker from CoinGecko
      DataSourceName: !GetAtt CoinGeckoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            method: 'GET',
            resourcePath: '/api/v3/simple/price',
            params: {
              query: {
                ids: ctx.args.symbol.toLowerCase(),
                vs_currencies: 'usd',
              },
              headers: {
                Accept: 'application/json',
              },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          if (ctx.result.statusCode !== 200) {
            util.error(`CoinGecko request failed: ${ctx.result.body}`, 'HttpError');
          }
          const symbol = ctx.args.symbol.toLowerCase();
          const body = JSON.parse(ctx.result.body);
          const entry = body[symbol];
          if (!entry || entry.usd === undefined || entry.usd === null) {
            util.error(`No price found for ticker ${ctx.args.symbol}`, 'NotFound');
          }
          return {
            ticker: symbol,
            priceUsd: entry.usd,
            timestamp: util.time.nowISO8601(),
          };
        }

  StorePriceFunction:
    Type: AWS::AppSync::FunctionConfiguration
    DependsOn: CryptoTickerSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      Name: StorePriceHistory
      Description: Stores a historical price record in DynamoDB
      DataSourceName: !GetAtt APIDataTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const record = ctx.prev.result;
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({
              hk: record.ticker,
              sk: record.timestamp,
            }),
            attributeValues: util.dynamodb.toMapValues({
              ticker: record.ticker,
              priceUsd: record.priceUsd,
              timestamp: record.timestamp,
            }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            ticker: ctx.result.ticker,
            priceUsd: ctx.result.priceUsd,
            timestamp: ctx.result.timestamp,
          };
        }

  TickerQueryResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: CryptoTickerSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      TypeName: Query
      FieldName: ticker
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt FetchPriceFunction.FunctionId
          - !GetAtt StorePriceFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  PriceHistoryResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: CryptoTickerSchema
    Properties:
      ApiId: !GetAtt CryptoTickerAPI.ApiId
      TypeName: TickerInfo
      FieldName: priceHistory
      Kind: UNIT
      DataSourceName: !GetAtt APIDataTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const limit = ctx.args.limit !== undefined && ctx.args.limit !== null ? ctx.args.limit : 25;
          const query = {
            operation: 'Query',
            query: {
              expression: '#hk = :hk',
              expressionNames: { '#hk': 'hk' },
              expressionValues: util.dynamodb.toMapValues({ ':hk': ctx.source.ticker }),
            },
            scanIndexForward: false,
            limit: limit,
          };
          if (ctx.args.nextToken) {
            query.nextToken = ctx.args.nextToken;
          }
          return query;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt CryptoTickerAPI.ApiId
  GraphQLApiUrl:
    Description: AppSync GraphQL endpoint URL
    Value: !GetAtt CryptoTickerAPI.GraphQLUrl
  GraphQLApiKey:
    Description: Default API key for CryptoTickerAPI
    Value: !GetAtt CryptoTickerApiKey.ApiKey
  APIDataTableName:
    Description: DynamoDB table storing historical ticker prices
    Value: !Ref APIDataTable

AWSTemplateFormatVersion: "2010-09-09"
Description: >
  Self-contained AWS AppSync GraphQL API (TodoAPIwithJs) with API key authentication,
  backed by a DynamoDB table with an owner GSI, using APPSYNC_JS pipeline resolvers
  for full CRUD, query-by-owner, and real-time subscriptions.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for TodoAPIwithJs

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

        type Todo {
          id: ID!
          name: String!
          description: String
          priority: Int
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          name: String!
          description: String
          priority: Int
          owner: String
        }

        input UpdateTodoInput {
          id: ID!
          name: String
          description: String
          priority: Int
          owner: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          queryTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  # ---------- Functions ----------

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: createTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const values = { ...ctx.args.input, createdAt: now, updatedAt: now };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(values),
            condition: {
              expression: 'attribute_not_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: updateTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const values = { updatedAt: util.time.nowISO8601() };
          for (const [key, value] of Object.entries(input)) {
            if (key !== 'id' && value !== null && value !== undefined) {
              values[key] = value;
            }
          }

          const expressionNames = { '#pk': 'id' };
          const expressionValues = {};
          const sets = [];
          for (const [key, value] of Object.entries(values)) {
            expressionNames[`#${key}`] = key;
            expressionValues[`:${key}`] = value;
            sets.push(`#${key} = :${key}`);
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: `SET ${sets.join(', ')}`,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: {
              expression: 'attribute_exists(#pk)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: deleteTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: getTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: listTodosFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit || 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: queryTodosByOwnerFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            limit: ctx.args.limit || 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  # ---------- Pipeline Resolvers ----------

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  UpdateTodoResolver:
