    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
