AWSTemplateFormatVersion: '2010-09-09'
Transform: AWS::Serverless-2016-10-31
Description: CloudFormation macro and backing Lambda function that dynamically generate IAM policies for the Datadog integration role.

Resources:
  DatadogPolicyMacroMacroFunction:
    Type: AWS::Serverless::Function
    Properties:
      FunctionName: DatadogPolicyMacroMacroFunction
      Description: Processes template fragments to generate Datadog IAM policy documents based on PolicyType.
      Runtime: python3.14
      Handler: index.handler
      MemorySize: 128
      Timeout: 30
      InlineCode: |
        import json
        import logging

        logger = logging.getLogger()
        logger.setLevel(logging.INFO)


        def _to_list(value):
            if value is None:
                return []
            if isinstance(value, list):
                return [v for v in value if v not in (None, "")]
            if isinstance(value, str):
                return [v.strip() for v in value.split(",") if v.strip()]
            return [value]


        def _bucket_resources(buckets, include_objects=True):
            resources = []
            for bucket in buckets:
                resources.append(f"arn:aws:s3:::{bucket}")
                if include_objects:
                    resources.append(f"arn:aws:s3:::{bucket}/*")
            return resources


        def log_archive_policy(buckets):
            return {
                "PolicyName": "DatadogLogArchiveAndRehydratePolicy",
                "PolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Sid": "DatadogUploadAndRehydrateLogArchives",
                            "Effect": "Allow",
                            "Action": ["s3:PutObject", "s3:GetObject"],
                            "Resource": [f"arn:aws:s3:::{b}/*" for b in buckets],
                        },
                        {
                            "Sid": "DatadogRehydrateLogArchivesListBucket",
                            "Effect": "Allow",
                            "Action": "s3:ListBucket",
                            "Resource": [f"arn:aws:s3:::{b}" for b in buckets],
                        },
                    ],
                },
            }


        def cloudtrail_policy(buckets):
            return {
                "PolicyName": "DatadogCloudTrailsPolicy",
                "PolicyDocument": {
                    "Version": "2012-10-17",
                    "Statement": [
                        {
                            "Sid": "DatadogCloudTrailBucketAccess",
                            "Effect": "Allow",
                            "Action": [
                                "s3:ListBucket",
                                "s3:GetBucketLocation",
                                "s3:GetObject",
                            ],
                            "Resource": _bucket_resources(buckets),
                        }
                    ],
                },
            }


        def handler(event, context):
            request_id = event.get("requestId")
            fragment = event.get("fragment")
            params = event.get("params", {}) or {}
            logger.info("Received event: %s", json.dumps(event))

            try:
                policy_type = params.get("PolicyType")
                buckets = _to_list(
                    params.get("Buckets", params.get("BucketNames", params.get("BucketName")))
                )

                if policy_type == "LogArchive":
                    if not buckets:
                        raise ValueError("At least one bucket is required for LogArchive policies")
                    result = log_archive_policy(buckets)
                elif policy_type == "CloudTrail":
                    if not buckets:
                        raise ValueError("At least one bucket is required for CloudTrail policies")
                    result = cloudtrail_policy(buckets)
                else:
                    result = fragment

                return {
                    "requestId": request_id,
                    "status": "success",
                    "fragment": result,
                }
            except Exception as exc:
                logger.exception("Failed to process macro fragment")
                return {
                    "requestId": request_id,
                    "status": "failure",
                    "fragment": fragment,
                    "errorMessage": str(exc),
                }

  DatadogPolicyMacro:
    Type: AWS::CloudFormation::Macro
    Properties:
      Name: DatadogPolicy
      Description: Dynamically generates IAM policies for the Datadog integration role.
      FunctionName: !GetAtt DatadogPolicyMacroMacroFunction.Arn

Outputs:
  MacroName:
    Description: Name of the CloudFormation macro
    Value: DatadogPolicy
  MacroFunctionArn:
    Description: ARN of the Lambda function backing the macro
    Value: !GetAtt DatadogPolicyMacroMacroFunction.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: Simple to-do list GraphQL API on AWS AppSync backed by DynamoDB, using JavaScript (APPSYNC_JS) resolvers and API key authentication.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
        - AttributeName: createdAt
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: createdAt
              KeyType: RANGE
          Projection:
            ProjectionType: ALL

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for testing SimpleTodoAPI

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          queryTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();
          const values = {
            owner: input.owner,
            title: input.title,
            completed: input.completed === undefined || input.completed === null ? false : input.completed,
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            values.description = input.description;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: util.autoId() }),
            attributeValues: util.dynamodb.toMapValues(values),
            condition: {
              expression: 'attribute_not_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const values = {};
          Object.keys(input).forEach((k) => {
            if (k !== 'id' && input[k] !== undefined && input[k] !== null) {
              values[k] = input[k];
            }
          });
          values.updatedAt = util.time.nowISO8601();

          const names = {};
          const vals = {};
          const sets = [];
          Object.keys(values).forEach((k) => {
            names[`#${k}`] = k;
            vals[`:${k}`] = values[k];
            sets.push(`#${k} = :${k}`);
          });
          names['#pk'] = 'id';

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: `SET ${sets.join(', ')}`,
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(vals),
            },
            condition: {
              expression: 'attribute_exists(#pk)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit || 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  QueryTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: queryTodosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            limit: ctx.args.limit || 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt TodoApi.ApiId
  GraphQLApiUrl:
    Description: AppSync GraphQL endpoint URL
    Value: !GetAtt TodoApi.GraphQLUrl
  GraphQLApiKey:
    Description: API key for SimpleTodoAPI
    Value: !GetAtt TodoApiKey.ApiKey
  TodoTableName:
    Description: DynamoDB table storing to-do items
    Value: !Ref TodoTable
